import os
import pandas as pd

def task_func(directory, file_list):
    # If no files specified, return an empty DataFrame.
    if not file_list:
        return pd.DataFrame()

    # List to store DataFrames read from each CSV file.
    dfs = []

    # Process each file in the list.
    for filename in file_list:
        file_path = os.path.join(directory, filename)
        # Check if the file exists; if not, raise FileNotFoundError.
        if not os.path.isfile(file_path):
            raise FileNotFoundError(f"File not found: {file_path}")

        # Read the CSV file into a DataFrame.
        df = pd.read_csv(file_path)
        dfs.append(df)

    # Concatenate all DataFrames along the rows, resetting the index.
    result = pd.concat(dfs, ignore_index=True)
    return result

